rss.channel:
{{ config.title }}
{{ config.base_url | safe }}
{{ config.description }}
Zola
{{ lang }}

{% if last_updated is defined %}{{ last_updated | date(format="%a, %d %b %Y %T %z") }}{% endif %}
{%- for page in pages %}


  {{ page.title }}
  {{ page.date | date(format="%a, %d %b %Y %T %z") }}
  {% for author in page.authors %}
  {{ author }}
  {% else %}
  {{ config.author }}
  {% endfor %}
  {{ page.permalink | safe }}
  {{ page.permalink | safe }}
  {% if page.summary %}
    {% set feed_source = page.summary %}
  {% else %}
    {% set feed_source = page.content %}
  {% endif %}
  {% set_global feed_body = "" %}
  {% for chunk in feed_source | split(pat="") %}
    {% if loop.first %}
      {% set_global feed_body = feed_body ~ chunk %}
    {% else %}
      {% set web_parts = chunk | split(pat="") %}
      {% set after_slideshow = web_parts | nth(n=1) %}
      {% set_global feed_body = feed_body ~ after_slideshow %}
    {% endif %}
  {% endfor %}
  {% set feed_body = feed_body
    | replace(from="", to="")
  %}
  {{ feed_body }}

{%- endfor %}
